package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository repository, Out<Sheet> sheet)
            throws SheetNotFoundException {
        Sheet found = repository.find(sheetId);
        if (found == null) {
            throw new SheetNotFoundException(sheetId);
        }
        sheet.set(found);
    }
}
# The sheet's last settle batch number (a bulk settle that settled at least one claim); null when none yet.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithLastBatch
  govern: [ readonly-transaction ]
import { HomeMain } from '../../slots/defs/homeMain';
import { ExportPeople } from './ExportPeople';

export const contribution = HomeMain.fill({ order: 21, Component: ExportPeople });
import { useClaims } from '../claims/claims';
import { gradeOn, liveHolds, usePeople } from '../people/people';
import { personDue, useRates } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useSheetToday } from '../session/sheetToday';
import { useDueRules } from '../settings/settings';

/** A CSV field: wrapped in double quotes, with any quote inside doubled, when it holds a comma, a quote or a line break. */
function csvField(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

// The button that downloads the people as a CSV file: one line per person in list order, retired
// people included, with the grade in force on the sheet's today, the retired-from date (or nothing)
// and the due-total as shown. Lines end with a line feed.
export function ExportPeople() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const today = useSheetToday();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();

  if (!user || !sheet) return null;

  const download = () => {
    const lines = [['name', 'grade', 'retired-from', 'due-total']];
    for (const p of people) {
      const due = personDue(claims.filter((c) => c.personId === p.id), rates, p.grades, liveHolds(p, rules.today), rules);
      lines.push([p.name, gradeOn(p.grades, today) ?? p.grade, p.retiredFrom ?? '', due]);
    }
    const csv = lines.map((l) => l.map(csvField).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `people-${sheet}.csv`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  return (
    <button type="button" data-testid="export-people" onClick={download}>
      Export people (CSV)
    </button>
  );
}
